-- AOC V33 ONBOARDING: REGISTER -> PIN -> IDENTITY -> HOME
create or replace function public.has_complete_identity() returns boolean language sql security definer stable set search_path=public,pg_temp as $$ select exists(select 1 from public.profiles p where p.id=auth.uid() and length(trim(coalesce(p.full_name,'')))>=3 and length(trim(coalesce(p.phone,'')))>=10 and length(trim(coalesce(p.city,'')))>=2 and length(trim(coalesce(p.address,'')))>=8); $$;
create or replace function public.set_home_security_pin(p_pin text) returns jsonb language plpgsql security definer set search_path=public,private,pg_temp as $$ declare v_user_id uuid:=auth.uid(); v_pin text:=trim(coalesce(p_pin,'')); v_until timestamptz; begin if v_user_id is null then raise exception 'Silakan login terlebih dahulu.'; end if; perform public.aoc_validate_home_pin(v_pin); insert into private.aoc_home_security_pins(user_id,pin_hash,failed_attempts,locked_until,updated_at) values(v_user_id,extensions.crypt(v_pin,extensions.gen_salt('bf',12)),0,null,now()) on conflict(user_id) do update set pin_hash=excluded.pin_hash,failed_attempts=0,locked_until=null,updated_at=now(); v_until:=now()+interval '10 minutes'; insert into private.aoc_home_security_pin_sessions(user_id,verified_until) values(v_user_id,v_until) on conflict(user_id) do update set verified_until=excluded.verified_until,created_at=now(); return jsonb_build_object('success',true,'message','PIN keamanan beranda berhasil disimpan.','verified_until',v_until); end; $$;
create or replace function public.get_home_security_pin_session() returns jsonb language sql security definer stable set search_path=public,private,pg_temp as $$ select jsonb_build_object('verified',exists(select 1 from private.aoc_home_security_pin_sessions s where s.user_id=auth.uid() and s.verified_until>now()),'verified_until',(select s.verified_until from private.aoc_home_security_pin_sessions s where s.user_id=auth.uid())); $$;
revoke all on function public.has_complete_identity() from public,anon,authenticated; grant execute on function public.has_complete_identity() to authenticated; revoke all on function public.set_home_security_pin(text) from public,anon,authenticated; grant execute on function public.set_home_security_pin(text) to authenticated; revoke all on function public.get_home_security_pin_session() from public,anon,authenticated; grant execute on function public.get_home_security_pin_session() to authenticated; notify pgrst,'reload schema';
